local function safe_tostring(value)
    local ok, rendered = pcall(tostring, value)
    return ok and rendered or '<tostring failed>'
end

local function safe_type(value)
    local ok, value_type = pcall(type, value)
    return ok and value_type or '<type failed>'
end

local function write_line(file, line)
    if not file then return end
    pcall(function()
        file:write(line .. '\n')
        file:flush()
    end)
end

local function log_value(file, key, value)
    write_line(file, key .. '=' .. safe_tostring(value))
end

local function open_log(loader)
    if loader and safe_type(loader.open_log) == 'function' then
        local ok, file = pcall(function() return loader.open_log(LOG_NAME) end)
        if ok and file then return file end
    end
    return nil
end

local function install_ffi_declarations(ffi)
    pcall(function()
        ffi.cdef [[
            void *GetModuleHandleA(const char *name);
            uint32_t GetModuleFileNameW(void *module, uint16_t *path, uint32_t capacity);
            void *GetCurrentProcess(void);
            uint32_t GetLastError(void);
            uint64_t GetTickCount64(void);
            int ReadProcessMemory(void *process, const void *address, void *buffer,
                                  size_t size, size_t *read);
            void *CreateFileW(const uint16_t *path, uint32_t access, uint32_t share,
                              void *security, uint32_t disposition, uint32_t flags,
                              void *template_file);
            int ReadFile(void *file, void *buffer, uint32_t size, uint32_t *read,
                         void *overlapped);
            int CloseHandle(void *handle);
        ]]
    end)
end

local function read_api(ffi, kernel)
    local process = kernel.GetCurrentProcess()
    local api = {}
    -- ReadProcessMemory is synchronous. Reuse scratch storage, but always
    -- return an owned Lua string so later reads cannot overwrite a result.
    -- Large resolver scans are temporary; retain at most 64 KiB for live reads.
    local capacity=256
    local buffer=ffi.new('uint8_t[?]',capacity)
    local count=ffi.new('size_t[1]')
    local pointer_value=ffi.new('uintptr_t[1]')
    function api.read(address, size)
        if not address or size < 1 or size > 262144 then return nil, 'invalid_request', 0, 0 end
        local target=buffer
        if size>65536 then target=ffi.new('uint8_t[?]',size)
        elseif size>capacity then
            repeat capacity=capacity*2 until capacity>=size
            buffer=ffi.new('uint8_t[?]',capacity);target=buffer
        end
        count[0]=0
        local success = kernel.ReadProcessMemory(process, ffi.cast('const void *',address), target, size, count)
        local error_code = success == 0 and tonumber(kernel.GetLastError()) or 0
        if success == 0 then return nil, 'read_failed', tonumber(count[0]), error_code end
        if tonumber(count[0]) ~= size then return nil, 'partial_read', tonumber(count[0]), error_code end
        return ffi.string(target, size), 'ok', tonumber(count[0]), 0
    end
    function api.pointer(bytes, offset)
        offset = offset or 0
        if not bytes or offset < 0 or offset + 8 > #bytes then return nil end
        ffi.copy(pointer_value, ffi.cast('const uint8_t *',bytes)+offset, 8)
        if tonumber(pointer_value[0]) < 0x10000 or tonumber(pointer_value[0]) >= 0x800000000000 then return nil end
        return ffi.cast('uint8_t *', tonumber(pointer_value[0]))
    end
    function api.u32(bytes, offset)
        if not bytes or offset < 0 or offset + 4 > #bytes then return nil end
        local a,b,c,d=bytes:byte(offset+1,offset+4)
        return a+b*256+c*65536+d*16777216
    end
    return api
end

local function pointer_text(ffi, pointer)
    if not pointer then return '<nil>' end
    return string.format('0x%X', tonumber(ffi.cast('uintptr_t', pointer)))
end


local JSON=(function()
local M={null={}}
local array_mt={}
function M.array(t) return setmetatable(t or {},array_mt) end
function M.is_array(t) return type(t)=='table' and getmetatable(t)==array_mt end
function M.encode(value)
    local function enc(v,depth)
        assert(depth<24,'JSON nesting limit')
        local kind=type(v)
        if v==M.null then return 'null' end
        if kind=='boolean' then return tostring(v) end
        if kind=='number' then assert(v==v and math.abs(v)<math.huge,'Invalid number');return tostring(v) end
        if kind=='string' then
            return '"'..v:gsub('[%z\1-\31\\"]',function(c)
                if c=='"' or c=='\\' then return '\\'..c end
                return string.format('\\u%04x',c:byte())
            end)..'"'
        end
        assert(kind=='table','Unsupported JSON type')
        local out={}
        if getmetatable(v)==array_mt then
            for i=1,#v do out[i]=enc(v[i],depth+1) end
            return '['..table.concat(out,',')..']'
        end
        local keys={};for k in pairs(v) do assert(type(k)=='string','Object key required');keys[#keys+1]=k end
        table.sort(keys)
        for _,k in ipairs(keys) do out[#out+1]=enc(k,depth+1)..':'..enc(v[k],depth+1) end
        return '{'..table.concat(out,',')..'}'
    end
    return enc(value,0)
end
function M.decode(text)
    assert(type(text)=='string' and #text<=262144,'JSON size limit')
    local at,n=1,#text
    local function skip() local _,last=text:find('^[ \r\n\t]*',at);at=(last or at-1)+1 end
    local function utf8(c)
        if c<128 then return string.char(c) end
        if c<2048 then return string.char(192+math.floor(c/64),128+c%64) end
        if c<65536 then return string.char(224+math.floor(c/4096),128+math.floor(c/64)%64,128+c%64) end
        return string.char(240+math.floor(c/262144),128+math.floor(c/4096)%64,128+math.floor(c/64)%64,128+c%64)
    end
    local function str()
        assert(text:sub(at,at)=='"','Expected string');at=at+1;local out={}
        while at<=n do
            local c=text:sub(at,at);at=at+1
            if c=='"' then return table.concat(out) end
            assert(c:byte()>=32,'Control character in string')
            if c=='\\' then
                c=text:sub(at,at);at=at+1
                local escapes={['"']='"',['\\']='\\',['/']='/',b='\b',f='\f',n='\n',r='\r',t='\t'}
                if c=='u' then
                    local h=text:sub(at,at+3);assert(h:match('^%x%x%x%x$'),'Invalid Unicode escape')
                    local cp=tonumber(h,16);at=at+4
                    if cp>=0xd800 and cp<=0xdbff then
                        assert(text:sub(at,at+1)=='\\u','Missing low surrogate');at=at+2
                        h=text:sub(at,at+3);assert(h:match('^%x%x%x%x$'),'Invalid low surrogate')
                        local low=tonumber(h,16);assert(low>=0xdc00 and low<=0xdfff,'Invalid low surrogate')
                        cp=0x10000+(cp-0xd800)*1024+low-0xdc00;at=at+4
                    else assert(cp<0xdc00 or cp>0xdfff,'Orphan surrogate') end
                    c=utf8(cp)
                else c=assert(escapes[c],'Invalid escape') end
            end
            out[#out+1]=c
        end
        error('Unterminated string')
    end
    local value
    value=function(depth)
        assert(depth<24,'JSON nesting limit');skip();local c=text:sub(at,at)
        if c=='"' then return str() end
        if c=='{' or c=='[' then
            local arr=c=='[';local result=arr and M.array() or {};at=at+1;skip()
            local close=arr and ']' or '}'
            if text:sub(at,at)==close then at=at+1;return result end
            while true do
                skip();local k=arr and #result+1 or str()
                if not arr then skip();assert(text:sub(at,at)==':','Expected colon');at=at+1;assert(result[k]==nil,'Duplicate key') end
                result[k]=value(depth+1);skip();local sep=text:sub(at,at);at=at+1
                if sep==close then return result end
                assert(sep==',','Expected comma')
            end
        end
        for token,v in pairs({['true']=true,['false']=false,['null']=M.null}) do
            if text:sub(at,at+#token-1)==token then at=at+#token;return v end
        end
        local begin=at
        if text:sub(at,at)=='-' then at=at+1 end
        local integer=text:match('^%d+',at);assert(integer and not integer:match('^0%d'),'Invalid JSON value')
        at=at+#integer
        if text:sub(at,at)=='.' then
            at=at+1;local digits=assert(text:match('^%d+',at),'Missing fractional digits');at=at+#digits
        end
        local e=text:sub(at,at)
        if e=='e' or e=='E' then
            at=at+1;local sign=text:sub(at,at);if sign=='+' or sign=='-' then at=at+1 end
            local digits=assert(text:match('^%d+',at),'Missing exponent digits');at=at+#digits
        end
        local token=text:sub(begin,at-1)
        local number=tonumber(token);assert(number and number==number and math.abs(number)<math.huge,'Invalid number')
        return number
    end
    local result=value(0);skip();assert(at>n,'Trailing JSON data');return result
end
return M

end)()
local Performance=(function()
-- Bounded counters only; no per-frame log writes or forced garbage collection.
local M={}
function M.new(report)
    local self={buckets={},next_report=0}
    function self:flush(now)
        for phase,b in pairs(self.buckets) do
            report('perf.tick',JSON.encode({phase=phase,samples=b.n,
                mean_ms=math.floor(b.total/b.n*1000000+0.5)/1000,
                max_ms=math.floor(b.maximum*1000000+0.5)/1000,over_8ms=b.slow}))
        end
        if next(self.buckets) then
            local ok,kib=pcall(collectgarbage,'count')
            if ok then report('perf.shared_lua_heap_kib',math.floor(kib+0.5)) end
        end
        self.buckets={};self.next_report=now+30000
    end
    function self:sample(phase,seconds,now)
        if self.next_report==0 then self.next_report=now+30000 end
        local b=self.buckets[phase]
        if not b then b={n=0,total=0,maximum=0,slow=0};self.buckets[phase]=b end
        seconds=math.max(0,seconds)
        b.n=b.n+1;b.total=b.total+seconds;b.maximum=math.max(b.maximum,seconds)
        if seconds>0.008 then b.slow=b.slow+1 end
        if now>=self.next_report then self:flush(now) end
    end
    return self
end
return M

end)()
