local I18n=(function()
-- Presentation only: action keys, saved names, IDs, native labels and logs are
-- not translated. This module never writes game memory or installs input hooks.
local M={language='en',revision=0}
local packs,fingerprints=Locales.packs,Locales.fingerprints
local cache,cache_count={},0
local aliases={
    ['Empty slot - select and save your equipment']='Select a slot and save your equipment',
    ['A preset is already being applied']='Wait for the current loadout to finish',
    ['Choose a vehicle, then a skin']='Choose a skin for each vehicle',
    ['Current equipment unavailable']='Current equipment unavailable; check DiverKit.log',
    ['Current character equipment unavailable']='Current equipment unavailable; check DiverKit.log',
    ['Unready before applying a preset']='Cancel Ready before applying a preset',
    ['Waiting for transmog adapter attachment']='Waiting for Transmog compatibility',
    ['Cannot hide equipment while loadout controls are transitioning']='Loadout screen is transitioning',
    ['loadout panel transitioning']='Loadout screen is transitioning',
    ['screen or player changed']='screen changed',
    ['Loadout screen changed']='screen changed',
    ['Copy a name to the clipboard first']='Copy a name, then click to paste (up to 96 UTF-8 bytes)',
    ['Copy only a short name']='Name must be 1-96 bytes without control characters',
    ['Empty or invalid name']='Name must be 1-96 bytes without control characters',
    ['Name exceeds 96 UTF-8 bytes']='Name must be 1-96 bytes without control characters',
    primary='Primary',pistol='Sidearm',grenade='Grenade',armor='Armor',helmet='Helmet',cape='Cape',
    stratagems='Stratagems',booster='Booster',title='Title',player_card='Player card',
    vehicle_skins='Vehicle skins',body_type='Body type',victory_pose='Victory pose',voice_pack='Voice pack',
}
local patterns={}
for key in pairs(packs.en) do
    if key:find('{',1,true) then
        local names={};local parts={};local at=1
        for start,name,finish in key:gmatch('(){([%w_]+)}()') do
            parts[#parts+1]=key:sub(at,start-1):gsub('([%^%$%(%)%%%.%[%]%*%+%-%?])','%%%1')
            names[#names+1]=name;parts[#parts+1]=(name=='n' or name=='max') and '(%d+)' or '(.+)'
            at=finish
        end
        parts[#parts+1]=key:sub(at):gsub('([%^%$%(%)%%%.%[%]%*%+%-%?])','%%%1')
        patterns[#patterns+1]={key=key,pattern='^'..table.concat(parts)..'$',names=names}
    end
end
table.sort(patterns,function(a,b) return #a.key==#b.key and a.key<b.key or #a.key>#b.key end)
function M.set_language(tag)
    if not packs[tag] then tag='en' end
    if tag==M.language then return false end
    M.language=tag;M.revision=M.revision+1;cache={};cache_count=0;return true
end
function M.detect(lookup)
    if type(lookup)~='function' then return nil end
    local ok,a,b=pcall(function() return lookup(0xF1A58533),lookup(0x2067F5A3) end)
    if not ok or type(a)~='string' or type(b)~='string' then return nil end
    a=a:match('^%s*(.-)%s*$');b=b:match('^%s*(.-)%s*$')
    for tag,pair in pairs(fingerprints) do if a==pair[1] and b==pair[2] then return tag end end
    return nil
end
-- Try at most once per five seconds while the panel is visible. A temporary
-- unavailable native localizer keeps the last good language (initially English).
function M.observer(report)
    local next_read=0;local reported
    return function(now,provider)
        if now<next_read then return false end
        next_read=now+5000
        local ok,lookup=pcall(provider)
        local tag=ok and M.detect(lookup) or nil
        local changed=tag and M.set_language(tag) or false
        local status=tag and ('game:'..tag) or ('unavailable:'..M.language)
        if reported~=status then
            reported=status;report('localization.language',M.language)
            report('localization.source',tag and 'game_text' or 'fallback_or_last_known')
        end
        return changed
    end
end
local function format(template,values)
    return (template:gsub('{([%w_]+)}',function(k) return values[k] or '{'..k..'}' end))
end
local translate
translate=function(value,depth)
    if type(value)~='string' or M.language=='en' or depth>5 then return value end
    local key=aliases[value] or value
    local exact=packs[M.language][key]
    if exact then return exact end
    local mark,rest=value:match('^(%[[ x]%] )(.*)$')
    if mark then return mark..translate(rest,depth+1) end
    -- Header pagination is an untranslated counter appended to a translated title.
    local page=value:match('^CHOOSE ICON(  %d+ / %d+)$')
    if page then return packs[M.language]['CHOOSE ICON']..page end
    local field,suffix=value:match('^([%w_]+)( [%(][0-9a-fA-FxX]+%))$')
    if not field then field,suffix=value:match('^([%w_]+)( %[[0-9a-fA-FxX]+%])$') end
    if field and aliases[field] then return translate(field,depth+1)..suffix end
    for _,p in ipairs(patterns) do
        local values={value:match(p.pattern)}
        if #values>0 then
            local named={};for i,k in ipairs(p.names) do named[k]=translate(values[i],depth+1) end
            return format(packs[M.language][p.key] or p.key,named)
        end
    end
    -- Diagnostic details remain intact if no known translation exists.
    return value
end
function M.text(value)
    if type(value)~='string' or M.language=='en' then return value end
    if cache[value]~=nil then return cache[value] end
    local result=translate(value,0)
    if cache_count>=512 then cache={};cache_count=0 end
    cache[value]=result;cache_count=cache_count+1;return result
end
-- A native label must never be treated as a translation key, even if its text
-- happens to match a button. Only explicitly marked generated fallbacks pass.
function M.label(item)
    return item and (item.label_fallback and M.text(item.label) or item.label)
end
-- Wrap at words, then at complete UTF-8 code points for CJK/unbroken words.
-- Width uses the current game font, never byte count or a second font atlas.
function M.wrap(value,measure,width)
    local lines,line={},''
    local function push() if line~='' then lines[#lines+1]=line:gsub('%s+$','');line='' end end
    for word in value:gmatch('%S+%s*') do
        if measure(line..word)<=width then line=line..word
        else
            push()
            if measure(word)<=width then line=word
            else
                for glyph in word:gmatch('[%z\1-\127\194-\244][\128-\191]*') do
                    if line~='' and measure(line..glyph)>width then push() end
                    line=line..glyph
                end
            end
        end
    end
    push();if #lines==0 then lines[1]='' end
    return lines
end
return M

end)()
