local M={aspect=art.aspect,triangle_count=art.triangles}
function M.draw(engine,gui,x,y,w,h,z)
    for n,layer in ipairs(art.layers) do
        local c=layer.color;local tint=engine.Color(c[1],c[2],c[3],c[4])
        local function point(v) return engine.Vector3(x+v[1]*w,0,y+v[2]*h) end
        for i=1,#layer.vertices,3 do
            engine.Gui.triangle(gui,point(layer.vertices[i]),point(layer.vertices[i+1]),point(layer.vertices[i+2]),z+n-1,tint)
        end
    end
end
return M

end)()
