        local members=JSON.array()
        for child,root in ipairs(roots) do if root==i then members[#members+1]=child-1 end end
        local choices=JSON.array()
        for j,item in ipairs(row.items) do
            local available=owned[item.value]
            for _,child in ipairs(members) do available=available and rows[child+1].ids[item.value] end
            if available then
                local name,generated=label(item.label_key,'Skin '..string.format('%02d',j))
                if item.value==0 then name,generated='Default',true end
                choices[#choices+1]={id=string.format('0x%08X',item.value),label=name,label_fallback=generated}
            end
        end
