        report('apply.primary_mod_slot',slot)
        if plan.payload_mode=='native_unmodified' or plan.payload_mode=='native_filtered_no_choices' then
            report('apply.primary_mods',plan.payload_mode)
        end
    end
    return plan
end
function M.check(context,plan)
    if not plan then return end
    assert(read(context,plan.global,8)==plan.profile,'Weapon configuration profile changed')
    if plan.entry then
        assert(read(context,plan.entry,M.stride)==plan.bytes,'Saved weapon configuration changed; retry')
        if plan.pending then assert(read(context,plan.base+0x12800,58)==plan.pending,'Weapon editor changed; retry') end
    end
end
function M.capture(context,primary)
    assert(Compat.verify(context),'Game compatibility evidence changed')
    local id=assert(tonumber(primary:sub(3),16),'Invalid primary weapon')
    assert(id~=0,'Primary weapon unavailable')
    local plan=lookup(context,id)
    local slot,source=1,'no_saved_configuration'
    if plan.entry then
        local active=context.api.u32(plan.bytes,8)
        assert(active==0xffffffff or active<M.slot_count,'Unknown weapon configuration layout')
        slot=active==0xffffffff and 1 or active+1
        source=active==0xffffffff and 'stock_default' or 'native_saved_slot'
        plan.pending=read(context,plan.base+0x12800,58)
        assert(context.api.u32(plan.pending,0)~=id or context.api.u32(plan.pending,4)==0xffffffff
            or plan.pending:sub(49,58)==string.rep('\0',10),'Finish editing weapon modifications in the Armory first')
    end
    local function check()
        M.check(context,plan)
        if not plan.entry then
            local again=lookup(context,id)
            assert(again.profile==plan.profile and not again.entry,'Weapon configuration changed; retry')
        end
