end
function M.apply(context,native,plan,check,changed)
    if not plan or not plan.switch then return end
    check();M.check(context,plan);assert(Compat.verify(context),'Game compatibility evidence changed')
    changed('primary_modifications')
    assert(native.weapon_mod_slot(plan.base,plan.id,plan.slot-1),'Weapon configuration switch rejected')
    local data=read(context,plan.entry,M.stride)
    assert(context.api.u32(data,8)==plan.slot-1,'Weapon configuration switch not confirmed')
    -- A slot selection must not overwrite saved attachment choices.
    assert(data:sub(13,132)==plan.bytes:sub(13,132),'Saved weapon configurations changed during selection')
