end)()
local function prepare(file)
    local ffi=require('ffi');install_ffi_declarations(ffi)
    local kernel=ffi.load('kernel32');local handle=kernel.GetModuleHandleA('game.dll')
    assert(handle~=nil,'game.dll missing')
    local context={ffi=ffi,kernel=kernel,game=ffi.cast('uint8_t *',handle),api=read_api(ffi,kernel)}
    context.private_override=false;context.private_multiselect=false
    -- 26251122: game.dll code did not move; 28 windows re-derived where .rdata moved and the exe
    -- witnesses remapped (builds/26251122/maps/diverkit/apply_26251122.py).
    -- Apply accepted on 26088801 (2026-10-29): weapons, helmet/cape, stratagems, booster and
    -- title validated in game; armour setter, card, character and paint enabled untested at
    -- the user's request. Title texture reads stay off.
    context.native_write_accepted=true;context.native_title_read_accepted=false
    context.private_report=function(k,v) log_value(file,k,v) end
    log_value(file,'compat.status','scanning')
    Compat.resolve(context,function(k,v) log_value(file,k,v) end,function() coroutine.yield() end)
    return context
end
-- Shared equipment reader. The adaptive addon supplies a resolved compatibility
-- context; historical probes retain their independently guarded reference layout.
local function read_equipment(api, game, owner, record, slot, context)
    local function rva(n) return context and Compat.address(context,n) or n end
    local enum_count=context and context.compat.stratagem_count or 150
    local watched={}
    local function read(address,size)
        local bytes=api.read(address,size)
        if bytes then watched[#watched+1]={address,size,bytes} end
        return bytes
    end
    local function pointer(address)
        local bytes=read(address,8)
        return api.pointer(bytes)
    end
    local result={gear_status='unavailable',stratagem_status='unavailable',gear={},stratagems={}}
    local raw=read(record+0x134,12)
    result.gear_raw=raw
    local function gear()
        if not raw then return 'fields_unreadable' end
        local catalog=pointer(game+rva(0x33264f8))
        if not catalog then return 'catalog_unavailable' end
        local header=read(catalog,12)
        local array,count=api.pointer(header),api.u32(header,8)
        if not array or not count or count<1 or count>2048 then return 'catalog_bounds_rejected' end
        -- Keep slot identity from the verified payload layout. A body item in
        -- the helmet field must not turn into a second armor match and discard
        -- the two healthy slots (for example, a headless cosmetic setup).
        local slots={{name='helmet',category=1},{name='cape',category=2},{name='armor',category=0}}
        local wanted={}
        for i,v in ipairs(slots) do
            v.id=api.u32(raw,(i-1)*4);v.bytes=raw:sub((i-1)*4+1,i*4)
            if v.id~=0 then wanted[v.id]=true end
        end
        local matched={}
        for first=0,count-1,32 do
            local entries=read(array+first*8,math.min(32,count-first)*8)
            if not entries then return 'catalog_unreadable' end
            for i=0,#entries/8-1 do
                local item=api.pointer(entries,i*8)
                if not item then return 'catalog_item_invalid' end
                local id=api.u32(api.read(item,4),0)
                if not id then return 'catalog_item_unreadable' end
                if wanted[id] then
                    local descriptor=read(item,44)
                    if not descriptor or api.u32(descriptor,0)~=id then return 'catalog_item_unreadable' end
                    local entry=matched[id]
                    matched[id]={category=api.u32(descriptor,40),duplicate=entry~=nil}
                end
            end
        end
        result.unavailable_fields={}
        for _,v in ipairs(slots) do
            result.gear[v.name]=v.bytes
            local match=matched[v.id]
            if not match or match.duplicate or match.category~=v.category then result.unavailable_fields[v.name]=true end
        end
        if next(result.unavailable_fields) then return 'unsupported_gear_slots' end
        return 'catalog_categories_matched_candidate'
    end
    result.gear_status=gear()

    local function stratagems()
        -- Match the displayed player card to the already identity-checked payload.
        -- Its four slot widgets preserve empty slots and user-visible ordering.
        local card
        for index=0,3 do
            local candidate=owner+0x53ab8+index*0x1ee18
            local header=read(candidate+0x1edf0,16)
            if api.pointer(header)==record+0x10 and api.u32(header,12)==slot then
                if card then return 'multiple_local_cards' end
                card=candidate
            end
        end
        if not card then return 'local_card_unavailable' end
        local count=api.u32(read(record+0x798,4),0)
        if not count or count>32 then return 'payload_count_rejected' end
        local available={}
        for i=0,count-1 do
            local value=api.u32(read(record+0x198+i*0x30,4),0)
            if not value or value>=enum_count then return 'payload_enum_rejected' end
            available[value]=(available[value] or 0)+1
        end
        local selected={}
        for i=0,3 do
            local handle=api.u32(read(card+0x5b78+0x8ec0+0x128c+i*0x12a8,4),0)
            if not handle or handle>=enum_count then return 'slot_enum_rejected' end
            local entry={slot=i+1,enum=handle,status='empty'}
            if handle~=0 then
                if not available[handle] or available[handle]<1 then return 'slot_payload_mismatch' end
                available[handle]=available[handle]-1
                local descriptor=pointer(game+rva(0x37cb600)+handle*8)
                if not descriptor then return 'descriptor_unavailable' end
                local enum=api.u32(read(descriptor,4),0)
                local flags=read(descriptor+0x80,1)
                if enum~=handle or not flags or math.floor(flags:byte()/2)%2~=1 then
                    return 'descriptor_rejected'
                end
                -- Native debug serializer indexes this read-only name table by enum.
                local name_ptr=pointer(game+rva(0x21d4dd0)+handle*8)
                if not name_ptr or (context and not Compat.readonly(context,name_ptr,128))
                    or (not context and (name_ptr<game+0x2111000 or name_ptr+128>game+0x263b98c)) then
                    return 'name_pointer_rejected'
                end
                local text=read(name_ptr,128)
                local name=text and text:match('^([^%z]+)%z')
                if not name or #name>96 or not name:match('^[A-Za-z_][A-Za-z0-9_]*$') then
                    return 'name_rejected'
                end
                entry.key=name;entry.status='candidate'
            end
            selected[i+1]=entry
        end
        result.stratagems=selected
        return 'four_ordered_slots_matched_candidate'
    end
    result.stratagem_status=stratagems()
    return result,function()
        for _,span in ipairs(watched) do
            if api.read(span[1],span[2])~=span[3] then return false end
        end
        return true
    end
end

-- A versioned, build-scoped snapshot. Unknown values stay null; empty stratagem
-- slots stay in place. This is an observation, never an instruction to apply IDs.
local function equipment_json(ids,extra,hex,context)
    local function quote(value)
        if value==nil then return 'null' end
        -- Only internally validated ASCII tokens/hex/status strings are serialized.
        assert(value:match('^[A-Za-z0-9_]+$'))
        return '"'..value..'"'
    end
    local function id(value) return value and quote(hex(value)) or 'null' end
    local complete=extra.gear.armor and extra.gear.helmet and extra.gear.cape and #extra.stratagems==4
    for _,name in ipairs({'primary','secondary','throwable'}) do
        if not ids[name] or ids[name]==string.rep('\0',4) then complete=false end
    end
    local entries={}
    for i=1,4 do
        local item=extra.stratagems[i]
        if not item or not item.key then complete=false end
        entries[i]='{"slot":'..i..',"key":'..quote(item and item.key)
            ..',"enum":'..(item and tostring(item.enum) or 'null')
            ..',"status":'..quote(item and item.status or 'unresolved')..'}'
    end
    local version=context and ('"schema_version":3,"source_version":"pe_'..context.compat.stamp..'"') or '"schema_version":2,"game_build":25327279'
    local unsupported={}
    for _,name in ipairs({'armor','helmet','cape'}) do
        if extra.unavailable_fields and extra.unavailable_fields[name] then unsupported[#unsupported+1]=quote(name)..':true' end
    end

    return '{'..version..',"status":'
        ..quote(complete and 'complete_candidate' or 'incomplete_candidate')
        ..',"primary":'..id(ids.primary)..',"pistol":'..id(ids.secondary)
        ..',"grenade":'..id(ids.throwable)..',"armor":'..id(extra.gear.armor)
        ..',"cape":'..id(extra.gear.cape)..',"helmet":'..id(extra.gear.helmet)
        ..',"unavailable_fields":{'..table.concat(unsupported,',')..'}'
        ..',"gear_status":'..quote(extra.gear_status)
        ..',"stratagem_status":'..quote(extra.stratagem_status)
        ..',"stratagems":['..table.concat(entries,',')..']}'
end

-- Appended to the common read/hash/header controls.
local CURRENT={manager=0x3326e68,session=0x347cef0,font=0x3772268,atlas=0x3772ee8,material=0x37c5478}
local function hex(bytes)
    if not bytes then return '<unreadable>' end
    local out={}
    for i=#bytes,1,-1 do out[#out+1]=string.format('%02X',bytes:byte(i)) end
    return '0x'..table.concat(out)
end
local function signatures_ok(file,context) return Compat.verify(context) end
local function sample_state(file, context)
    local api,game,ffi=context.api,context.game,context.ffi
    assert(context.kernel.GetModuleHandleA('game.dll')==ffi.cast('void *',game),'module changed')
    local function read(address,size,key)
        local bytes,status,count,code=api.read(address,size)
        if not bytes then
            log_value(file,key..'.read_status',status)
            log_value(file,key..'.bytes_read',count)
            log_value(file,key..'.win32_error',code)
        end
        return bytes
    end
    local manager,session
    for name,rva in pairs(CURRENT) do
        local key='anchor.'..name
        local bytes=read(game+Compat.address(context,rva),8,key)
        log_value(file,key..'.raw_u64',hex(bytes))
        if name=='font' or name=='atlas' then
            log_value(file,key..'.kind','resource_id64')
        else
            local pointer=api.pointer(bytes)
            log_value(file,key..'.pointer',pointer_text(ffi,pointer))
            if pointer then
                log_value(file,key..'.target_readable',read(pointer,8,key..'.target')~=nil)
            end
            if name=='manager' then manager=pointer end
            if name=='session' then session=pointer end
        end
    end
    if not manager then log_value(file,'loadout.status','manager_unavailable');return end
    -- Current on_enter registers owner/type 0xE5 at manager+0x62A8,
    -- with count at +0x62A0. The next bucket starts at +0x62B8: capacity is one.
    local bucket=read(manager+0x6390,24,'loadout.registry')
    if not bucket then log_value(file,'loadout.status','registry_unreadable');return end
    local count,kind=api.u32(bucket,0),api.u32(bucket,16)
    log_value(file,'loadout.registry.count',count)
    log_value(file,'loadout.registry.kind',kind)
    if count==0 then log_value(file,'loadout.status','not_registered');return end
    if count~=1 or kind~=0xe7 then log_value(file,'loadout.status','layout_rejected');return end
    local owner=api.pointer(bucket,8)
    if not owner then log_value(file,'loadout.status','owner_invalid');return end
    -- No peer identifiers or arbitrary object dumps. These two flag spans are
    -- explicitly read/written by the current MenuScreenLoadout on_enter code.
    local flags=read(owner+0x2838,8,'loadout.flags')
    local state=read(owner+0x2848,8,'loadout.state')
    local slot_bytes=read(owner+0x2810,4,'loadout.local_slot')
    local slot=api.u32(slot_bytes,0)
    local local_status,ids,extra,additional='slot_or_session_unavailable',nil,nil,nil
    if session and slot and slot<4 then
        -- Current update compares this record's peer to session+0xB398.
        -- Peer values are used for equality only and are never logged.
        local peer=read(session+0xb398,8,'local.peer')
        local record=owner+slot*0xa00
        local record_peer=read(record+0xa08,8,'local.record_peer')
        if peer and peer~=string.rep('\0',8) and record_peer==peer then
            ids={}
            for _,field in ipairs({{'primary',0x10},{'secondary',0x70},{'throwable',0xd0}}) do
                ids[field[1]]=read(record+field[2],4,'local.'..field[1])
            end
            local stable
            extra,stable=read_equipment(api,game,owner,record,slot,context)
            local extra_stable
            additional,extra_stable=Extras.capture(context,record+0x10)
            local same_equipment=stable()
            local same_ids=true
            for _,field in ipairs({{'primary',0x10},{'secondary',0x70},{'throwable',0xd0}}) do
                if not ids[field[1]] or api.read(record+field[2],4)~=ids[field[1]] then same_ids=false end
            end
            local session_bytes=api.read(game+Compat.address(context,CURRENT.session),8)
            if not same_equipment or not same_ids or not extra_stable() or api.pointer(session_bytes)~=session
                or api.read(owner+0x2810,4)~=slot_bytes
                or api.read(session+0xb398,8)~=peer or api.read(record+0xa08,8)~=peer then
                ids=nil;local_status='changed_or_unreadable'
            else local_status='local_slot_matched_candidate_fields' end
        else local_status='local_identity_unmatched' end
    end
    local manager_bytes=api.read(game+Compat.address(context,CURRENT.manager),8)
    local same_manager=api.pointer(manager_bytes)==manager
    local same_bucket=api.read(manager+0x6390,24)==bucket
    if not same_manager or not same_bucket then
        log_value(file,'loadout.status','changed_during_sample');return
    end
    log_value(file,'loadout.owner',pointer_text(ffi,owner))
    log_value(file,'loadout.flags_27f8',hex(flags))
    log_value(file,'loadout.state_2808',hex(state))
    log_value(file,'loadout.status',flags and state and 'registered_owner_readable' or 'owner_unreadable')
    log_value(file,'local.status',local_status)
    if ids then
        log_value(file,'local.slot',slot)
        for _,name in ipairs({'primary','secondary','throwable'}) do
            log_value(file,'local.'..name..'_id32_candidate',hex(ids[name]))
        end
        log_value(file,'local.gear.status',extra.gear_status)
        for i=0,2 do
            if extra.gear_raw then
                log_value(file,'local.gear.field_'..string.format('%X',0x134+i*4),hex(extra.gear_raw:sub(i*4+1,i*4+4)))
            end
        end
        for _,name in ipairs({'armor','cape','helmet'}) do
            if extra.gear[name] then log_value(file,'local.'..name..'_id32_candidate',hex(extra.gear[name])) end
        end
        log_value(file,'local.stratagems.status',extra.stratagem_status)
        local snapshot=JSON.decode(equipment_json(ids,extra,hex,context))
        snapshot.schema_version=4
        for _,name in ipairs(Extras.fields) do snapshot[name]=additional[name] end
        local character_ok,character=pcall(Character.capture,context,owner+slot*0xa00+0x10)
        context.character_error=not character_ok and tostring(character) or nil
        if character_ok then for _,name in ipairs(Character.fields) do snapshot[name]=character[name] end end
        -- A temporarily unavailable optional skin block must not disable saving
        -- ordinary equipment. Applying a saved skin selection still fails closed.
        local skins_ok,skins=pcall(VehicleSkins.capture,context,owner+slot*0xa00+0x10)
        context.vehicle_skins_error=not skins_ok and tostring(skins) or nil
        if skins_ok then snapshot.vehicle_skins=skins
        else log_value(file,'local.vehicle_skins_unavailable',tostring(skins)) end
        local encoded=JSON.encode(snapshot)
        log_value(file,'loadout.snapshot_json',encoded)
        return encoded
    end
end


local Model=(function()
local M={fields={'primary','pistol','grenade','armor','cape','helmet'},max_presets=100,default_slots=15,primary_mod_slots=3}
M.categories={'primary','pistol','grenade','armor','helmet','cape','stratagems','booster','title','player_card'}
-- Keep the public item-category contract used by Transmog 0.1.3/0.1.5.
-- Paints are a structured extension (twelve IDs), not a single item ID.
M.apply_categories={};for i,k in ipairs(M.categories) do M.apply_categories[i]=k end
M.apply_categories[#M.apply_categories+1]='vehicle_skins'
M.character_fields={'body_type','victory_pose','voice_pack'}
for _,k in ipairs(M.character_fields) do M.apply_categories[#M.apply_categories+1]=k end
M.labels={primary='Primary',pistol='Sidearm',grenade='Grenade',armor='Armor',helmet='Helmet',cape='Cape',stratagems='Stratagems',booster='Booster',title='Title',player_card='Player card',vehicle_skins='Vehicle skins'}
M.labels.body_type='Body type';M.labels.victory_pose='Victory pose';M.labels.voice_pack='Voice pack'
function M.mask(value,kind)
    local out={}
    for i,k in ipairs(M.apply_categories) do
        if kind~='random' or i<=8 then
            out[k]=value==nil and (kind~='random' or k~='booster') or value~=nil and value[k]==true
        end
    end
    return out
end
function M.any(mask,snapshot)
    for k,v in pairs(mask) do if v and (not snapshot or snapshot[k]~=nil) then return true end end
    return false
end
local function validate_mask(mask,kind)
    assert(type(mask)=='table' and not JSON.is_array(mask),'Invalid equipment selection')
    local allowed=M.mask(nil,kind)
    for k,v in pairs(mask) do assert(allowed[k]~=nil and type(v)=='boolean','Invalid equipment selection: '..tostring(k)) end
end
function M.panel_layout(value)
    if value==nil then return {scale=100,x=0,y=0,locked=true} end
    assert(type(value)=='table' and not JSON.is_array(value),'Invalid panel layout')
    for key in pairs(value) do assert(key=='scale' or key=='x' or key=='y' or key=='locked' or key=='free','Invalid panel layout field') end
    assert(value.free==nil or type(value.free)=='boolean','Invalid free panel position')
    assert(value.locked==nil or type(value.locked)=='boolean','Invalid panel lock')
    assert(type(value.scale)=='number' and value.scale%1==0 and value.scale>=50 and value.scale<=175,'Invalid panel scale')
    assert(type(value.x)=='number' and value.x>=-1 and value.x<=1,'Invalid panel horizontal position')
    assert(type(value.y)=='number' and value.y>=-1 and value.y<=1,'Invalid panel vertical position')
    return {scale=value.scale,x=value.x,y=value.y,locked=value.locked~=false,free=value.free==true}
end
function M.settings(db)
    local settings=db.settings or {}
    return {random_fields=M.mask(settings.random_fields,'random'),background=settings.background or 1,
        hide_randomized=settings.hide_randomized==true,panel_collapsed=settings.panel_collapsed==true,
        auto_apply_last_played=settings.auto_apply_last_played==true,last_played_preset_id=settings.last_played_preset_id,
        ministry_override=settings.ministry_override==true,
        panel_layout=M.panel_layout(settings.panel_layout)}
end
function M.slot_count(db) return db.slot_count or M.default_slots end
function M.slot_index(db,slot)
    for i,p in ipairs(db.presets) do if (p.slot or i)==slot then return i end end
end
local function id(v) return type(v)=='string' and #v==10 and v:match('^0x%x+$') and v~='0x00000000' end
local subfaction_ids={
    ['subfaction:predator_strain']=true,
    ['subfaction:spore_burst_strain']=true,
    ['subfaction:rupture_strain']=true,
    ['subfaction:jet_brigade']=true,
    ['subfaction:incineration_corps']=true,
    ['subfaction:cyborg_legion']=true,
    ['subfaction:appropriators']=true,
    ['subfaction:vote_snatchers']=true,
    ['subfaction:mindless_masses']=true,
    ['subfaction:invasion_fleet']=true,
}
local function stratagem_icon_id(v)
    if type(v)~='string' then return false end
