local extra_icon_ids={}
for _,icon in ipairs(GameIcons) do extra_icon_ids[icon.id]=true end
local function icon_id(v)
    return id(v) or (type(v)=='string' and extra_icon_ids[v]) or stratagem_icon_id(v) or (type(v)=='string' and subfaction_ids[v]) or v=='faction:terminids' or v=='faction:automatons' or v=='faction:illuminate'
        or v=='resource:sample_common' or v=='resource:sample_rare' or v=='resource:sample_super'
        or v=='resource:super_credits' or v=='resource:medal'
end
function M.validate_snapshot(s)
    assert(type(s)=='table' and (s.schema_version==2 or s.schema_version==3 or s.schema_version==4),'Unsupported loadout version')
    if s.schema_version==2 then assert(type(s.game_build)=='number' and s.game_build>0 and s.game_build%1==0,'Invalid source build')
    else assert(type(s.source_version)=='string' and #s.source_version<=96 and s.source_version:match('^[A-Za-z0-9_]+$'),'Invalid source version') end
    if s.unavailable_fields~=nil then
        assert(type(s.unavailable_fields)=='table' and s.unavailable_fields~=JSON.null and not JSON.is_array(s.unavailable_fields),'Invalid unavailable fields')
        for k,v in pairs(s.unavailable_fields) do assert((k=='armor' or k=='helmet' or k=='cape') and v==true,'Invalid unavailable field') end
    end
    for _,k in ipairs(M.fields) do
        assert(id(s[k]) or s.unavailable_fields and s.unavailable_fields[k] and s[k]=='0x00000000','Missing equipment: '..k)
    end
    if s.schema_version==4 then
        for _,k in ipairs({'title','player_card','booster'}) do
            assert(id(s[k]) or s[k]=='0x00000000','Missing equipment: '..k)
        end
    end
    if s.vehicle_skins~=nil then
        assert(s.schema_version==4 and JSON.is_array(s.vehicle_skins) and #s.vehicle_skins==12,'Invalid vehicle skin selection')
        for _,v in ipairs(s.vehicle_skins) do assert(id(v) or v=='0x00000000','Invalid vehicle skin ID') end
    end
    for _,k in ipairs(M.character_fields) do
        if s[k]~=nil then assert(s.schema_version==4 and (id(s[k]) or k=='voice_pack' and s[k]=='random'),'Invalid character selection: '..k) end
    end
    assert(s.primary_mod_slot==nil or type(s.primary_mod_slot)=='number' and s.primary_mod_slot%1==0 and s.primary_mod_slot>=1 and s.primary_mod_slot<=M.primary_mod_slots,'Invalid primary weapon configuration slot')
    assert(JSON.is_array(s.stratagems) and #s.stratagems==4,'Four slots required')
    for i,v in ipairs(s.stratagems) do
        assert(type(v)=='table' and v.slot==i and type(v.enum)=='number' and v.enum%1==0 and v.enum>=0 and v.enum<=4294967295,'Invalid stratagem slot')
        assert(v.enum==0 and v.key==JSON.null or v.enum>0 and type(v.key)=='string' and #v.key<=96 and v.key:match('^[A-Za-z_][A-Za-z0-9_]*$'),'Invalid stratagem key')
    end
    return s
end
function M.copy_snapshot(s)
    M.validate_snapshot(s)
    local out={schema_version=s.schema_version==4 and 4 or 3,source_version=s.source_version or ('legacy_'..s.game_build),stratagems=JSON.array()}
    for _,k in ipairs(M.fields) do out[k]=s[k] end
    out.primary_mod_slot=s.primary_mod_slot
    if s.unavailable_fields and next(s.unavailable_fields) then
        out.unavailable_fields={};for k,v in pairs(s.unavailable_fields) do out.unavailable_fields[k]=v end
    end
    if s.schema_version==4 then for _,k in ipairs({'title','player_card','booster'}) do out[k]=s[k] end end
    for _,k in ipairs(M.character_fields) do out[k]=s[k] end
    if s.vehicle_skins then out.vehicle_skins=JSON.array();for i,v in ipairs(s.vehicle_skins) do out.vehicle_skins[i]=v end end
    for i,v in ipairs(s.stratagems) do out.stratagems[i]={slot=i,key=v.key,enum=v.enum} end
    return out
end
function M.validate(db)
    assert(type(db)=='table' and db.format=='codex-hd2-loadouts' and db.version==1,'Unsupported preset file')
    assert(type(db.next_id)=='number' and db.next_id%1==0 and db.next_id>0 and db.next_id<1000000,'Invalid next ID')
    if db.settings~=nil then
        assert(type(db.settings)=='table' and not JSON.is_array(db.settings),'Invalid settings')
        if db.settings.random_fields~=nil then validate_mask(db.settings.random_fields,'random') end
        assert(db.settings.hide_randomized==nil or type(db.settings.hide_randomized)=='boolean','Invalid hidden random setting')
        assert(db.settings.panel_collapsed==nil or type(db.settings.panel_collapsed)=='boolean','Invalid panel visibility setting')
        assert(db.settings.auto_apply_last_played==nil or type(db.settings.auto_apply_last_played)=='boolean','Invalid auto-apply setting')
        assert(db.settings.ministry_override==nil or type(db.settings.ministry_override)=='boolean','Invalid Ministry Override setting')
        local last=db.settings.last_played_preset_id
        assert(last==nil or type(last)=='number' and last%1==0 and last>0 and last<db.next_id,'Invalid last played preset')
        local level=db.settings.background
        assert(level==nil or level==1 or level==2 or level==3,'Invalid background level')
        M.panel_layout(db.settings.panel_layout)
    end
    local count=M.slot_count(db)
    assert(type(count)=='number' and count%1==0 and count>=1 and count<=M.max_presets,'Invalid slot count')
    -- Hidden slots remain intact when the player reduces the visible count.
    assert(JSON.is_array(db.presets) and #db.presets<=M.max_presets,'Preset limit')
    local used,slots={},{}
    for i,p in ipairs(db.presets) do
        local slot=p.slot or i
        assert(type(slot)=='number' and slot%1==0 and slot>=1 and slot<=M.max_presets and not slots[slot],'Invalid preset slot')
        slots[slot]=true
        assert(type(p)=='table' and type(p.id)=='number' and p.id%1==0 and p.id>0 and p.id<db.next_id and not used[p.id],'Invalid preset ID')
        used[p.id]=true
        assert(type(p.name)=='string' and #p.name>0 and #p.name<=96 and not p.name:find('[%z\1-\31;]'),'Invalid preset name')
        assert(p.icon_title_id==JSON.null or icon_id(p.icon_title_id),'Invalid icon ID')
        assert(p.icon_secondary_id==nil or p.icon_secondary_id==JSON.null or icon_id(p.icon_secondary_id),'Invalid second icon ID')
        M.validate_snapshot(p.loadout)
        if p.apply_fields~=nil then validate_mask(p.apply_fields,'apply') end
        assert(p.armory_pending==nil or type(p.armory_pending)=='boolean','Invalid Armory save marker')
    end
    return db
end
function M.empty() return {format='codex-hd2-loadouts',version=1,next_id=1,presets=JSON.array()} end
function M.compose(saved,current,fields)
    M.validate_snapshot(saved)
    if fields==nil then return M.copy_snapshot(saved) end
    validate_mask(fields,'apply')
    local mask=M.mask(fields,'apply')
    assert(M.any(mask,saved),'Select at least one saved equipment category')
    local out=M.copy_snapshot(current)
    if mask.primary then out.primary_mod_slot=saved.primary_mod_slot end
    for _,k in ipairs(M.apply_categories) do
        if mask[k] and saved[k]~=nil then
            assert(out[k]~=nil,'Current equipment unavailable: '..k)
            out[k]=(k=='stratagems' or k=='vehicle_skins') and M.copy_snapshot(saved)[k] or saved[k]
            if out.unavailable_fields then out.unavailable_fields[k]=nil end
            if saved.unavailable_fields and saved.unavailable_fields[k] then
                out.unavailable_fields=out.unavailable_fields or {};out.unavailable_fields[k]=true
            end
        end
    end
    -- Transmog keeps its armor recipe beside the armor it was saved with, and checks the two
    -- agree; the copy of current carries the recipe of the armor being replaced.
    if mask.armor and saved.armor~=nil then out.transmog=saved.transmog end
    -- Old saves do not contain character cosmetics or a booster.
    if saved.schema_version~=4 then
        out.schema_version=3;out.title=nil;out.player_card=nil;out.booster=nil;out.vehicle_skins=nil
        for _,k in ipairs(M.character_fields) do out[k]=nil end
    end
    return M.validate_snapshot(out)
end
function M.new(fs)
    local self={db=M.empty(),locked=false,notice='',load_diagnostics={},load_status='new'}
    local function failed(name,stage,why)
        local reason=tostring(why)
        local runtime=reason:find('table overflow',1,true) or reason:find('not enough memory',1,true)
            or reason:find('memory allocation',1,true)
        self.load_diagnostics[#self.load_diagnostics+1]={file=name,stage=stage,reason=reason,
            kind=runtime and 'runtime' or stage}
        return nil,runtime and 'runtime' or stage
    end
    local function load(name)
        local read,text,why=pcall(fs.read,name)
        if not read then return failed(name,'read',text) end
