        local ok,copy=pcall(M.copy_snapshot,snapshot)
        if not ok then return false,'Select equipment on the loadout screen first' end
        local db=JSON.decode(JSON.encode(self.db))
        if index then
            if not db.presets[index] then return false,'No preset selected' end
            local preset=db.presets[index]
            if from_armory then
                -- Armory has no mission selection. Preserve those saved fields.
                local previous=M.copy_snapshot(preset.loadout)
                copy.stratagems=previous.stratagems
                copy.booster=previous.booster or copy.booster
                if previous.booster==nil then preset.apply_fields=M.mask(preset.apply_fields,'apply');preset.apply_fields.booster=false end
                if copy.vehicle_skins==nil then copy.vehicle_skins=previous.vehicle_skins end
                for _,key in ipairs(M.character_fields) do if copy[key]==nil then copy[key]=previous[key] end end
            elseif preset.armory_pending then
                -- The first normal pre-drop overwrite completes the new kit.
                preset.apply_fields=M.mask(preset.apply_fields,'apply')
                preset.apply_fields.stratagems=true;preset.apply_fields.booster=true
                preset.armory_pending=nil
            end
            preset.loadout=copy
        else
            if not slot then for n=1,M.slot_count(db) do if not M.slot_index(db,n) then slot=n;break end end end
            if not slot or slot%1~=0 or slot<1 or slot>M.slot_count(db) then return false,'All visible slots are full' end
            if M.slot_index(db,slot) then return false,'Slot already occupied' end
            db.presets[#db.presets+1]={id=db.next_id,slot=slot,name='Preset '..slot,icon_title_id=JSON.null,loadout=copy}
            db.next_id=db.next_id+1
        end
        local saved=db.presets[index or #db.presets]
        if from_armory and not index then
            saved.apply_fields=M.mask(nil,'apply')
            saved.apply_fields.stratagems=false;saved.apply_fields.booster=false
            saved.armory_pending=true
        end
        local skipped={}
        for _,k in ipairs(M.fields) do
            if copy.unavailable_fields and copy.unavailable_fields[k] then
                saved.apply_fields=M.mask(saved.apply_fields,'apply');saved.apply_fields[k]=false
                skipped[#skipped+1]=M.labels[k]
            end
        end
        local ok,message=commit(db)
        return ok,ok and #skipped>0 and ('Saved; unsupported '..table.concat(skipped,', ')..' excluded') or message
    end
    function self:save_armory(snapshot,index,slot) return self:save(snapshot,index,slot,true) end
    function self:move_slot(from,to,expected_id)
        if self.locked then return false,self.notice end
        local count=M.slot_count(self.db)
        for _,slot in ipairs({from,to}) do
            if type(slot)~='number' or slot%1~=0 or slot<1 or slot>count then return false,'Invalid preset slot' end
        end
        if from==nil or to==nil then return false,'Invalid preset slot' end
        local source=M.slot_index(self.db,from);local destination=M.slot_index(self.db,to)
        if not source then return false,'Source slot is empty' end
        if expected_id and self.db.presets[source].id~=expected_id then return false,'Preset changed; drag it again' end
        if from==to then return true,'Preset position unchanged' end
        local db=JSON.decode(JSON.encode(self.db))
        db.presets[source].slot=to
        if destination then db.presets[destination].slot=from end
        local ok,message=commit(db)
        return ok,ok and (destination and 'Presets swapped' or 'Preset moved') or message
    end
    function self:remove(index)
