        return commit(db)
    end
    function self:set_ministry_override(value)
        if type(value)~='boolean' then return false,'Invalid Ministry Override setting' end
        local db=JSON.decode(JSON.encode(self.db));db.settings=M.settings(db);db.settings.ministry_override=value
        return commit(db)
    end
    function self:set_auto_apply_last_played(value)
        if type(value)~='boolean' then return false,'Invalid auto-apply setting' end
        local db=JSON.decode(JSON.encode(self.db));db.settings=M.settings(db);db.settings.auto_apply_last_played=value
        local ok,message=commit(db)
        return ok,ok and (value and 'Auto-apply enabled for the next deployment' or 'Auto-apply disabled') or message
    end
    function self:remember_played(id)
