        if not found then return false,'Last played preset no longer exists' end
        if M.settings(self.db).last_played_preset_id==id then return true,'Last played preset unchanged' end
        local db=JSON.decode(JSON.encode(self.db));db.settings=M.settings(db);db.settings.last_played_preset_id=id
        return commit(db)
    end
