        local db=JSON.decode(JSON.encode(self.db));db.presets[index].name=name
        local ok,why=pcall(M.validate,db);if not ok then return false,'Name must be 1-96 bytes without control characters' end
        return commit(db)
    end
    function self:set_random_fields(fields)
        local valid=pcall(validate_mask,fields,'random');if not valid then return false,'Invalid random selection' end
        local db=JSON.decode(JSON.encode(self.db));db.settings=M.settings(db);db.settings.random_fields=M.mask(fields,'random')
        return commit(db)
    end
    function self:set_background(level)
        if level~=1 and level~=2 and level~=3 then return false,'Invalid background level' end
        local db=JSON.decode(JSON.encode(self.db));db.settings=M.settings(db);db.settings.background=level
        return commit(db)
    end
    function self:set_hide_randomized(value)
        if type(value)~='boolean' then return false,'Invalid hidden random setting' end
        local db=JSON.decode(JSON.encode(self.db));db.settings=M.settings(db);db.settings.hide_randomized=value
        local ok,message=commit(db)
        return ok,ok and (value and 'Next random loadout will be hidden' or 'Random loadout revealed') or message
    end
    function self:set_panel_collapsed(value)
        if type(value)~='boolean' then return false,'Invalid panel visibility setting' end
        local db=JSON.decode(JSON.encode(self.db));db.settings=M.settings(db);db.settings.panel_collapsed=value
        return commit(db)
    end
    function self:set_panel_layout(value)
        local valid,layout=pcall(M.panel_layout,value)
