        if slot~=nil and (type(slot)~='number' or slot%1~=0 or slot<1 or slot>M.primary_mod_slots) then return false,'Invalid primary weapon configuration slot' end
        local db=JSON.decode(JSON.encode(self.db));db.presets[index].loadout.primary_mod_slot=slot
