local Files=(function()
local M={}
local path_declared,rotate_declared,files_declared
local function path_converter(ffi,kernel,directory)
    if not path_declared then
        ffi.cdef[[int MultiByteToWideChar(unsigned int,unsigned long,const char*,int,uint16_t*,int);]]
        path_declared=true
    end
    assert(type(directory)=='string' and #directory>5 and not directory:find('\0',1,true),'Invalid directory path')
    -- Loader versions using os.getenv/CreateDirectoryA can supply Windows ACP
    -- bytes. Preserve UTF-8 paths; only invalid UTF-8 falls back to the current
    -- Windows ANSI code page (never a hard-coded language-specific code page).
    local codepage,label=65001,'utf8'
    local n=kernel.MultiByteToWideChar(codepage,8,directory,#directory,nil,0)
    if n==0 then
        local err=tonumber(kernel.GetLastError())
        assert(err==1113,'Path conversion failed: '..err)
        codepage,label=0,'windows_acp'
        n=kernel.MultiByteToWideChar(codepage,8,directory,#directory,nil,0)
        assert(n>0,'Windows path conversion failed: '..tonumber(kernel.GetLastError()))
    end
    local function wide(text)
        local count=kernel.MultiByteToWideChar(codepage,8,text,#text,nil,0)
        assert(count>0,'Path conversion failed: '..tonumber(kernel.GetLastError()))
        local value=ffi.new('uint16_t[?]',count+1)
        assert(kernel.MultiByteToWideChar(codepage,8,text,#text,value,count)==count,'Path conversion failed')
        return value
    end
    return wide,label
end
function M.rotate_log(ffi,kernel,directory)
    assert(type(directory)=='string' and #directory>5,'Log directory unavailable')
    if not rotate_declared then ffi.cdef[[
        int CopyFileW(const uint16_t*,const uint16_t*,int);
        uint32_t GetFileAttributesW(const uint16_t*);
    ]];rotate_declared=true end
    local wide,encoding=path_converter(ffi,kernel,directory)
    local function path(name) return wide(directory..'/'..name) end
    local names={'DiverKit.log','DiverKit.previous.log','DiverKit.previous-2.log','DiverKit.previous-3.log'}
    for i=#names-1,1,-1 do
        local source=path(names[i])
        if tonumber(kernel.GetFileAttributesW(source))~=0xffffffff then
            assert(kernel.CopyFileW(source,path(names[i+1]),0)~=0,'Cannot preserve '..names[i])
        else assert(kernel.GetLastError()==2 or kernel.GetLastError()==3,'Cannot inspect previous log') end
    end
    return encoding
end
function M.new(ffi,kernel,directory)
