local Screen=(function()
local M={}
-- Keep a roll concealed across the landing-map/equipment tab switch, but never
-- carry concealment into a later deployment. No native state is modified.
function M.redaction_scope(context)
    local api,game=context.api,context.game
    local bytes=api.read(game+Compat.address(context,CURRENT.manager),8)
    local manager=api.pointer(bytes)
    local session_bytes=api.read(game+Compat.address(context,CURRENT.session),8)
    local session=api.pointer(session_bytes)
    if not manager or not session then return nil end
    local bucket=api.read(manager+0x6390,24)
    if not bucket or api.u32(bucket,0)~=1 or api.u32(bucket,16)~=0xe7 or not api.pointer(bucket,8) then return nil end
    local peer=api.read(session+0xb398,8)
    if not peer or peer==string.rep('\0',8) then return nil end
    if api.read(manager+0x6390,24)~=bucket or api.read(game+Compat.address(context,CURRENT.session),8)~=session_bytes then return nil end
    return bytes..session_bytes..bucket..peer
end
function M.redaction_box(context,anchor,detail)
    if not anchor or not detail or not detail.card then return nil end
    -- Read the existing Ready widget: never estimate a height that could cover it.
    local widget=context.api.read(detail.card+0x28b0,164)
    if not widget or require('bit').band(context.api.u32(widget,0),0x10)==0 then return nil end
    local function float(offset)
        local v=context.ffi.new('float[1]');context.ffi.copy(v,widget:sub(offset+1,offset+4),4)
        return tonumber(v[0])
    end
    local opacity,sx,sy=float(84),float(100),float(140)
    local x,y,w,h=float(148),float(156),float(36)*sx,float(40)*sy
    for _,v in ipairs({opacity,sx,sy,x,y,w,h}) do if v~=v or v<0 or v>32768 then return nil end end
    if opacity<0.995 or opacity>1.01 or sx<0.3 or sx>4 or math.abs(sx-sy)>0.01 then return nil end
    local scale=anchor.w/420
    if math.abs(x-anchor.x)>8*scale or math.abs(w-anchor.w)>16*scale or h<10 then return nil end
    local bottom=y+h+2*scale;local top=anchor.y-2*scale
    if top-bottom<120*scale or top-bottom>600*scale then return nil end
    return {x=anchor.x,y=bottom,w=anchor.w,h=top-bottom}
end
-- Cheap visibility/identity check; the complete reader still runs before saving.
function M.identity(context)
    local api,game=context.api,context.game
    local manager_bytes=api.read(game+Compat.address(context,CURRENT.manager),8)
    local session_bytes=api.read(game+Compat.address(context,CURRENT.session),8)
    local manager,session=api.pointer(manager_bytes),api.pointer(session_bytes)
    if not manager or not session then return nil end
    local bucket=api.read(manager+0x6390,24)
    if not bucket or api.u32(bucket,0)~=1 or api.u32(bucket,16)~=0xe7 then return nil end
    local owner=api.pointer(bucket,8)
    if not owner then return nil end
    -- set_view at 0x1470d00: 0 = landing map, 1 = stratagem loadout.
    local view_bytes=api.read(owner+8,4)
    if not view_bytes or api.u32(view_bytes,0)~=1 then return nil end
