    -- Do not create/destroy our GUI or acquire input on that transitional card.
    if api.read(owner+0x2739d0,1)~='\0' or api.read(owner+0x2848,1)~='\0' then return nil end
    local slot_bytes=api.read(owner+0x2810,4)
    local slot=slot_bytes and api.u32(slot_bytes,0)
