    HellbombBackpack=true,MissionHellbombBackpack=true,BallisticShield=true,DirectionalEnergyShield=true,
    DroneMG=true,Drone_Laser_Rifle=true,Drone_Stun=true,Drone_FLAMETHROWER=true,Drone_GASPROJECTOR=true}
