        report('ministry_override.enabled',enabled)
        report('ownership_checks',not enabled)
        report('duplicate_stratagems_allowed',enabled)
    end
    function self:reset() self.position=0;self.started=nil;self.scope=nil end
    function self:step(key,now,scope)
        -- The caller supplies no scope when the menu is closed/covered, input
        -- loses focus, storage is read-only, or a loadout is being applied.
        if not scope then self:reset();return end
        if self.scope~=scope or self.started and (now<self.started or now-self.started>timeout) then self:reset() end
        self.scope=scope
        if not key then return end
        if key~=sequence[self.position+1] then self:reset();self.scope=scope end
        if key==sequence[self.position+1] then
            if self.position==0 then self.started=now end
            self.position=self.position+1
        end
        if self.position~=#sequence then return end
        self:reset()
        local enabled=not Model.settings(store.db).ministry_override
        local ok,why=store:set_ministry_override(enabled)
        report('ministry_override.saved',ok)
        if not ok then return why end
        -- Commit first: a failed write must not silently enable a session-only
        -- bypass or leave the behavior different after restarting the game.
        sync()
        return enabled and 'ACCESS GRANTED — Ministry Override enabled.' or 'ACCESS REVOKED — Ministry Override disabled.'
    end
    self:reset();sync()
    return self
end
return M

end)()
local Armory=(function()
