    functions(p.armor_tab,{'ensure_session'},'Transmog Armory session')
    functions(p.actor,{'new'},'Transmog player factory')
    functions(p.EquippedState,{'matches','resolve_target'},'Transmog saved variant')
    functions(p.mods.AppearancePatch,{'compatible'},'Transmog composition')
    assert(type(p.patch_active)=='function' and type(p.startup)=='table' and type(p.st)=='table'
        and type(p.store)=='table' and type(p.catalog)=='table','Transmog Armory services unavailable')
    local token=assert(Armory.identity(context),'Open the Armory first')
    local function identity()
        return gate:attached() and rawget(_G,'HD2Transmog')==p.peer and p.peer.diverkit_compat==p.adapter
            and Armory.identity(context)==token
    end
