        assert(identity(),'Transmog Armory context changed')
        assert(not(p.store.locked or p.patch_active() or p.startup.active
            or p.st.session and p.st.session:busy() or p.st.flow and p.st.flow:is_open()),
            'Finish the current Transmog operation first')
    end
    idle()
    if not p.catalog.result and type(p.catalog.update)=='function' then p.catalog.update() end
    local result=assert(p.catalog.result,'Open Armor once to finish catalog verification, then retry')
    local record=target.transmog;local id=ident(target.armor)
    local request=record and {appearance_id=record.appearance_id,stats_id=record.stats_id,
        passive_variant_id=record.passive_variant_id,id=record.variant_id} or result.catalog[id]
    assert(request,'Original armor is unavailable')
    local logical=request.appearance_id:match('^clothing:')~=nil
    local intent=record and {label=record.label,request=request,target_id=id,version=record.version,
        logical_id=logical and request.appearance_id or nil}
    if logical then
        id=assert(p.EquippedState.resolve_target(intent,result.context),'Saved clothing binding is unavailable')
        assert(id:match('^armor:%x%x%x%x%x%x%x%x$'),'Invalid clothing carrier')
        target.armor='0x'..id:sub(7):upper()
    end
