        assert(identity() and p.catalog.result==result,'Transmog catalog or Armory context changed')
        if record then assert(p.EquippedState.matches(intent,p.store.domain,id,result.context),
            'Saved Transmog variant was removed or changed; save the DiverKit preset again') end
        if logical then assert(p.EquippedState.resolve_target(intent,result.context)==id,'Saved clothing binding changed') end
        local allowed,why=p.mods.AppearancePatch.compatible(result,request);assert(allowed==true,why)
        local donors={}
        for _,field in ipairs({'appearance_id','stats_id','passive_variant_id'}) do
            local donor
            for kit_id,kit in pairs(result.catalog) do
                if result.owned[kit_id] and kit[field]==request[field]
                    and (field=='appearance_id' or not kit_id:match('^clothing:')) then donor=kit_id;break end
            end
