end
function M.new(context,capture,report,gate)
    report=report or function()end
    local plain=ArmoryApply.new(context,capture,report)
    local others=ArmoryApply.new(context,function()return Armory.capture(context)end,function(k,v)
        report(k:gsub('^armory%.apply','armory.equipment'),v)
    end,{defer_preview=true})
