        if self.busy then return false,'A preset is already being applied' end
        local ok,value=pcall(function()
            local current=assert(capture(),'Current equipment unavailable')
            fields=ArmoryApply.fields(mask);target=Model.compose(snapshot,current,fields)
            assert(Model.any(fields,target),'Select at least one equipment or appearance category')
            local custom=target.transmog or current.transmog or gate and gate:attached() and gate:armory_active()
            if not custom then return false end
            -- Validate every ordinary field before Transmog or equipment writes.
            local other_fields=ArmoryApply.fields(fields);other_fields.armor=false
            token=assert(Armory.identity(context),'Open the Armory first')
            local has_others=Model.any(other_fields,target)
            if has_others then ArmoryApply.preflight(context,Apply.bind(context),target,Armory.capture(context),other_fields,report) end
            local prepared=M.prepare(context,gate,target,report)
            op=prepared;started=now;stage=has_others and 'equipment' or 'armor'
            if has_others then
                local accepted,message=others:start(target,now,other_fields)
                if not accepted then error(message) end
            end
            report('armory.transmog.requested',target.transmog and target.transmog.label or 'original armor')
            self.busy=true;return true
        end)
