            assert(Armory.identity(context)==token,'Armory closed or player changed')
            assert(gate:attached(),'Transmog adapter disconnected')
            if stage=='equipment' then
                local result=others:poll(now)
                if others.busy then return end
                assert(result=='Preset applied',result or 'Other equipment was not verified')
                stage='armor'
            end
            if stage=='armor' then
                local began,why=op.begin(now);assert(began,why);stage='verify'
            end
            local phase,why=op.poll(now)
            if phase=='failed' then error(why or 'Transmog application failed') end
            if phase~='complete' then return end
            local current=assert(capture(),'Current equipment unavailable')
            assert(#Apply.differences(target,current,fields)==0
                and (not fields.vehicle_skins or VehicleSkins.same(target.vehicle_skins,current.vehicle_skins)),
                'Equipment changed during Transmog application')
