    function self.report(key,value)
        if key=='apply.booster' then self.booster_incomplete=value=='skipped_squad_incomplete' end
        if key=='apply.vehicle_skins_skipped' then self.skin_skipped=true end
        if key=='apply.result' and value=='verified' then return end
