        if self.started and now then report('apply.total_elapsed_ms',now-self.started) end
        local verified_id
        if message=='Preset applied' or message=='Preset applied; booster in use - skipped' then
            verified_id=self.id
            if self.id~=nil then report('apply.preset',self.id) end
            report('apply.result','verified')
            -- Keep the native success strings understood by Transmog until its
            -- complete operation finishes. Only the final UI notice gains this
            -- warning; failed or pending armor operations never look successful.
            if self.booster_incomplete then
                message='Preset applied; booster skipped - squad data incomplete'
            end
            if self.skin_skipped then
                message=message..'; vehicle skins skipped (catalog mismatch)'
            end
        else
            report('apply.error',message);report('apply.result','not_verified')
        end
        self:reset()
        return message,verified_id
    end
    return self
end
