end)()
local LastPlayed=(function()
-- Read-only deployment observation. A verified apply is merely a candidate;
-- only mission mode with the loadout screen gone can commit its stable ID.
local M={}
local function encoded(value) return JSON.encode(value==nil and JSON.null or value) end
local function preset(db,id)
    for _,p in ipairs(db.presets) do if p.id==id then return p end end
end
local function definition(p) return JSON.encode({loadout=p.loadout,fields=p.apply_fields}) end
local function readers(context)
    local api=context.api;local spans={}
    local function read(at,n)
        local b=assert(api.read(at,n),'Deployment data unavailable')
        assert(#b==n,'Partial deployment data');spans[#spans+1]={at,n,b};return b
    end
    local function u32(at) return assert(api.u32(read(at,4),0),'Invalid deployment value') end
    local function pointer(at) return assert(api.pointer((read(at,8))),'Deployment pointer unavailable') end
    local function global(rva) return context.game+Compat.address(context,rva) end
    local function check()
        for _,v in ipairs(spans) do assert(api.read(v[1],v[2])==v[3],'Deployment changed during sample') end
    end
    return read,u32,pointer,global,check
end
function M.mode(context)
    -- Guard this optional observer independently; never call a native function.
    local proven=false
    for _,p in ipairs(context.compat.proofs) do
        if p.name=='last_played_mission_mode' then
            assert(context.api.read(context.game+p.rva,#p.bytes)==p.bytes,'Deployment mode evidence changed');proven=true;break
        end
    end
    assert(proven,'Deployment mode unresolved')
    local _,u32,pointer,global,check=readers(context)
    local mode=u32(pointer(global(0x3326340))+0xac21c);check();return mode
end
function M.identity(context)
    local read,_,pointer,global,check=readers(context)
    local peer=read(pointer(global(0x347cef0))+0xb398,8)
    assert(peer~=string.rep('\0',8),'Local player unavailable');check();return peer
end
function M.mission_matches(context,candidate)
    local read,u32,pointer,global,check=readers(context)
    local peer=read(pointer(global(0x347cef0))+0xb398,8)
    if peer~=candidate.peer then return false end
    local players=pointer(global(0x347ce50));local count=u32(players+0x2d800)
    assert(count>=1 and count<=32,'Player records unavailable')
    local payload
    for i=0,count-1 do
        local at=players+i*0x16c0
        if read(at,8)==peer then assert(not payload,'Ambiguous local player');payload=at+0x38 end
    end
    assert(payload,'Local mission equipment unavailable')
    local values={}
    for name,offset in pairs({primary=0,pistol=0x60,grenade=0xc0,body_type=0x120,
        helmet=0x124,cape=0x128,armor=0x12c,booster=0x130,voice_pack=0x134,
        victory_pose=0x138,player_card=0x13c,title=0x144}) do
        if candidate.fields[name] and candidate.snapshot[name]~=nil then
            values[name]=string.format('0x%08X',u32(payload+offset))
        end
    end
    if values.voice_pack and read(payload+0x148,1):byte()==1 then values.voice_pack='random' end
    if candidate.fields.vehicle_skins and candidate.snapshot.vehicle_skins then
        assert(u32(payload+0x14c)==12,'Unknown mission paint layout')
        values.vehicle_skins=JSON.array()
        for i=1,12 do values.vehicle_skins[i]=string.format('0x%08X',u32(payload+0x14c+i*4)) end
    end
    for name,value in pairs(values) do
        if JSON.encode(value)~=JSON.encode(candidate.snapshot[name]) then return false end
    end
    if candidate.fields.stratagems then
        -- Session payload includes mission-issued calls as well as selected calls.
        -- Check multiplicity, not array position; UI order was captured at apply.
        local n=u32(payload+0x788);assert(n<=32,'Mission stratagem count rejected')
        local have={}
        for i=0,n-1 do
            local enum=u32(payload+0x188+i*0x30)
            assert(enum<context.compat.stratagem_count,'Mission stratagem enum rejected')
            have[enum]=(have[enum] or 0)+1
        end
        for _,v in ipairs(candidate.snapshot.stratagems) do
            if v.enum~=0 then
                if not have[v.enum] or have[v.enum]<1 then return false end
                have[v.enum]=have[v.enum]-1
            end
        end
    end
    if candidate.fields.primary and candidate.snapshot.primary_mod_slot and not WeaponMods.mission_matches(context,payload,candidate.snapshot) then return false end
    check();return true
end
function M.new(context,store,report)
    local self={next_poll=0,spent=true}
    function self:cancel_auto() self.spent=true end
    function self:clear_candidate() self.candidate=nil end
    function self:accepted(id,snapshot)
        self.candidate=nil
        local p=preset(store.db,id)
        if not p or not snapshot or not self.scope then return end
        local fields=Model.mask(p.apply_fields,'apply')
        for k in pairs(fields) do if p.loadout[k]==nil then fields[k]=false end end
        if not Model.any(fields,p.loadout) then return end
        if fields.stratagems then
            for _,v in ipairs(snapshot.stratagems) do if v.enum==0 then return end end
        end
        local ok,peer=pcall(M.identity,context)
        if not ok then report('last_played.capture_error',peer);return end
        self.candidate={id=id,snapshot=Model.copy_snapshot(snapshot),fields=fields,peer=peer,definition=definition(p)}
        if fields.primary then self.candidate.snapshot.primary_mod_slot=p.loadout.primary_mod_slot or 1 end
        report('last_played.candidate',id)
    end
    function self:sample(snapshot)
        local c=self.candidate
        if not c or not snapshot then return end
        for k,on in pairs(c.fields) do
            if on and c.snapshot[k]~=nil and encoded(c.snapshot[k])~=encoded(snapshot[k]) then
                self.candidate=nil;report('last_played.candidate_cleared','equipment_changed');return
            end
        end
        if c.fields.armor and encoded(c.snapshot.transmog)~=encoded(snapshot.transmog) then
            self.candidate=nil;report('last_played.candidate_cleared','transmog_changed')
        end
    end
    function self:observe(scope,now)
        if scope~=self.scope then
            if scope then
                -- A single failed registry read must not reapply a preset.
                if scope~=self.previous_scope or not self.left or now-self.left>=1500 then
                    self.candidate=nil;self.mission_since=nil;self.entered=nil
                    self.spent=not Model.settings(store.db).auto_apply_last_played
                    self.auto_id=Model.settings(store.db).last_played_preset_id
                end
            else self.left=now;self.previous_scope=self.scope end
            self.scope=scope
        end
        if now<self.next_poll then return end
        self.next_poll=now+500
        -- A few small guarded reads per half second; no catalogs or GUI work.
        local ok,mode=pcall(M.mode,context)
        if not ok then
            if self.error~=tostring(mode) then self.error=tostring(mode);report('last_played.observer_error',mode) end
            self.mission_since=nil;return
        end
        self.error=nil
        if self.mode~=mode then self.mode=mode;report('last_played.game_mode',mode) end
        if scope or mode~=4 or not self.candidate then self.mission_since=nil;return end
        if not self.left or now-self.left>120000 then self.candidate=nil;return end
        local p=preset(store.db,self.candidate.id)
        if not p or definition(p)~=self.candidate.definition then self.candidate=nil;return end
        self.mission_since=self.mission_since or now
        if now-self.mission_since<2000 then return end
        local matched,why=pcall(M.mission_matches,context,self.candidate)
        if matched and why then
            local id=self.candidate.id;self.candidate=nil
            local saved,message=store:remember_played(id)
            report('last_played.mission_confirmed',id);report('last_played.saved',saved)
            if not saved then report('last_played.save_error',message) end
        elseif now-self.mission_since>=30000 then
            self.candidate=nil;report('last_played.not_remembered',matched and 'mission_equipment_changed' or tostring(why))
        end
    end
    function self:due(now,ready)
        if self.spent or not self.scope then return end
        if not Model.settings(store.db).auto_apply_last_played or store.locked then self.spent=true;return end
        if not self.auto_id then self.spent=true;return end
        self.entered=self.entered or now -- Start waiting on the equipment screen, not the landing map.
        if now-self.entered>30000 then self.spent=true;report('auto_apply.skipped','screen_not_ready');return end
        if now-self.entered<1000 or not ready then return end
        self.spent=true
        local p=preset(store.db,self.auto_id)
        if not p then report('auto_apply.skipped','preset_missing');return end
        report('auto_apply.preset',p.id);return p
    end
    return self
end
return M

end)()
