            local ok,saved,message=pcall(Cosmetics.select,context,store,selected_index(),state.cosmetic_kind,value,capture())
            if not ok then return false,'Cannot select: '..tostring(saved):gsub('^.-:%d+: ','') end
            if saved then state.editor='apply' end
            return saved,message
        end) end
        if clicked and clicked:match('^skin:category:') then
            state.skin_category=tonumber(clicked:sub(15));state.skin_page=1
            state.notice='Saved to this preset; equipped when applied'
        end
        if clicked=='skin:back' then
            if state.skin_category~=nil then state.skin_category=nil;state.skin_page=1
            else state.editor='apply' end
        end
        if clicked=='skin:prev' then state.skin_page=math.max(1,(state.skin_page or 1)-1) end
        if clicked=='skin:next' then
            local choices=state.skin_catalog or {}
            for _,row in ipairs(state.skin_catalog or {}) do if row.category==state.skin_category then choices=row.choices;break end end
            state.skin_page=math.min(math.max(1,math.ceil(#choices/7)),(state.skin_page or 1)+1)
        end
        if clicked and clicked:match('^skin:pick:') then action('skin',now,function()
            local ok,saved,message=pcall(Cosmetics.select_skin,context,store,selected_index(),state.skin_category,clicked:sub(11),capture())
            if not ok then report('cosmetics.skin_error',saved);return false,'Cannot select: '..tostring(saved):gsub('^.-:%d+: ','') end
            if saved then state.skin_category=nil;state.skin_page=1 end
            return saved,message
        end) end
        if clicked=='editor:close' then state.editor=nil end
        if clicked=='background' then action('background',now,function()
            return store:set_background(Model.settings(store.db).background%3+1)
        end) end
        if clicked=='random:hide' then action('hide_randomized',now,function()
            local value=not Model.settings(store.db).hide_randomized
            local ok,message=store:set_hide_randomized(value)
            if ok and not value then state.random_hidden=false end
            return ok,message
        end) end
        if clicked=='rename' then action('rename',now,function()
            local name,why=Clipboard.read_name(ffi,kernel)
            if not name then return false,why end
            return store:rename(selected_index(),name)
        end) end
        if clicked and clicked:match('^field:') then action('fields',now,function()
            local key=clicked:sub(7)
            if state.editor=='random' then
                local fields=Model.settings(store.db).random_fields;fields[key]=not fields[key]
                return store:set_random_fields(fields)
            end
            local preset=store.db.presets[selected_index()]
            if not preset then return false,'No preset selected' end
            local fields=Model.mask(preset.apply_fields,'apply');fields[key]=not fields[key]
            return store:set_apply_fields(selected_index(),fields)
        end) end
        if clicked=='iconprev' then state.icon_page=math.max(1,(state.icon_page or 1)-1) end
        if clicked=='iconnext' then state.icon_page=math.min(math.max(1,math.ceil(#icons/60)),(state.icon_page or 1)+1) end
        if clicked=='slots:less' or clicked=='slots:more' then
            action('slot_count',now,function()
                local count=Model.slot_count(store.db)+(clicked=='slots:more' and 1 or -1)
                local ok,message=store:set_slot_count(count)
                if ok then
                    state.selected=math.min(state.selected,count);state.picker=false;state.hover=nil
                    state.confirm=nil;last_slot_click=nil;surface:clear();pointer:reset()
                    report('presets.slot_count',count)
                end
                return ok,message
            end)
        end
        if clicked and clicked:match('^select:') then
            local slot=tonumber(clicked:sub(8))
            if slot and slot>=1 and slot<=Model.slot_count(store.db) then
                local double=last_slot_click and last_slot_click.slot==slot and now>=last_slot_click.at and now-last_slot_click.at<=450
                state.selected=slot;state.picker=false;state.editor=nil
                local saved=selected_index()~=nil
                state.notice=state.sorting and 'Use arrows to move or swap presets' or saved and 'Double-click to apply' or 'Select a slot and save your equipment'
                if double and saved and not state.sorting then clicked='apply';last_slot_click=nil
                else last_slot_click=not state.sorting and saved and {slot=slot,at=now} or nil end
            end
        end
        if clicked=='create' then action('create',now,function()
            local snapshot,why=capture_for_save();if not snapshot then return false,why end
            local ok,message=store:save(snapshot,nil,state.selected)
            if ok then last_played:accepted(store.db.presets[selected_index()].id,snapshot) end
            return ok,message
        end) end
        if clicked=='overwrite' then action('overwrite',now,function()
            local snapshot,why=capture_for_save();if not snapshot then return false,why end
            local ok,message=store:save(snapshot,selected_index())
            if ok then last_played:accepted(store.db.presets[selected_index()].id,snapshot) end
            return ok,message
        end) end
        local auto_preset=last_played:due(now,not clicked and not input.down and not activation.busy
            and current~=nil and not state.apply_reason and transmog:ready()
            and not state.menu and not state.editor and not state.sorting and not state.drag)
        if auto_preset then
            clicked='apply'
            if auto_preset.slot<=Model.slot_count(store.db) then state.selected=auto_preset.slot end
        end
        if clicked=='apply' then
            local preset=auto_preset or store.db.presets[selected_index()]
            if preset then
                last_played:clear_candidate()
                state.confirm=nil;state.picker=false;state.applying_random=false
                local needs_transmog=preset.loadout.transmog and (preset.apply_fields==nil or preset.apply_fields.armor)
                local ok,message
                if not activation.busy then apply_events:reset() end
                if needs_transmog and not transmog:attached() then
                    ok=false;message='Cannot apply: saved armor requires a connected Transmog adapter'
                else ok,message=activation:start(preset.loadout,now,preset.apply_fields) end
                if ok then state.random_hidden=false;apply_events:accepted(preset.id,now) end
                state.notice=message;next_sample=0;report('action.apply',ok)
                if not ok then report('action.apply_reason',message) end
            end
        end
        if clicked=='randomize:run' then action('randomize',now,function()
            state.confirm=nil;state.picker=false
            local hide=Model.settings(store.db).hide_randomized
            if hide and (not scope or not cover) then
                return false,'Cannot hide equipment while loadout controls are transitioning'
            end
            state.random_sequence=(state.random_sequence or 0)+1
            local ok,target=pcall(function()
                return Randomize.generate(context,assert(capture(),'Current equipment unavailable'),
                    now+state.random_sequence*104729,report,Model.settings(store.db).random_fields)
            end)
            if not ok then
                report('randomize.error',target)
                return false,'Cannot randomize: '..tostring(target):gsub('^.-:%d+: ','')
            end
            if not activation.busy then apply_events:reset() end
            local accepted,message=activation:start(target,now,Model.settings(store.db).random_fields)
            if accepted then
                last_played:clear_candidate()
                apply_events:accepted(nil,now)
                state.random_hidden=hide
                report('randomize.hidden',hide)
            end
            state.applying_random=accepted;next_sample=0
            return accepted,accepted and 'Randomizing loadout...' or message
        end) end
        if clicked=='delete' then action('delete',now,function()
            local ok,message=store:remove(selected_index());if ok then state.picker=false end;return ok,message
        end) end
        if clicked=='iconclear' then action('icon',now,function()
            local ok,message=store:icon(selected_index(),JSON.null,state.icon_slot);if ok then state.picker=false end;return ok,message
        end) end
        if clicked and clicked:match('^iconpick:') then
            local id=clicked:sub(10)
            for _,icon in ipairs(icons) do if icon.id==id then
                action('icon',now,function()
                    local ok,message=store:icon(selected_index(),id,state.icon_slot);if ok then state.picker=false end;return ok,message
                end)
                break
            end end
        end
        if not previews and state.editor=='skins' and state.skin_category~=nil then
            previews=SkinPreviews.new(context,engine,report,function() surface:clear() end)
        end
        if previews then
            local preset=store.db.presets[selected_index()]
            previews:step(now,state,preset and preset.loadout.vehicle_skins or current and current.vehicle_skins)
        end
        if now>=next_ui then
            local settings=Model.settings(store.db)
            local ok,why=pcall(function() surface:draw({presets=store.db.presets,selected=state.selected,slot_count=Model.slot_count(store.db),
                render_revision=math.floor(now/1000)..':'..render_revision,
                sorting=state.sorting,
                auto_apply_last_played=settings.auto_apply_last_played,
                current=current or JSON.null,notice=state.notice,icons=icons,anchor=anchor,menu=state.menu,collapsed=state.collapsed,
                picker=state.picker,icon_page=state.icon_page or 1,icon_slot=state.icon_slot or 1,hover=state.hover,locked=store.locked,busy=activation.busy,
                editor=state.editor,random_fields=settings.random_fields,background=settings.background,
                panel_layout=state.drag_layout or settings.panel_layout,
                hide_randomized=settings.hide_randomized,redaction=state.random_hidden and cover or nil,
                pad_focus=hotkeys.active and hotkeys.focus or nil,
                lock_reason=store.notice,apply_reason=state.apply_reason,
                cosmetic_kind=state.cosmetic_kind,cosmetic_page=state.cosmetic_page or 1,cosmetic_choices=state.cosmetic_choices,
                skin_catalog=state.skin_catalog,skin_category=state.skin_category,skin_page=state.skin_page or 1,
                skin_preview_revision=previews and previews.revision or 0,skin_preview_status=previews and previews.status,
                confirm=state.confirm and state.confirm.kind or JSON.null},handles(),previews) end)
            if surface.icon_error and surface.icon_error~=state.last_icon_error then report('icon.error',surface.icon_error);state.last_icon_error=surface.icon_error end
            if not ok then
                pcall(function() surface:clear() end);pointer:reset();report('ui.error',why);next_ui=now+5000
            end
        end
    end
    -- LLL owns scheduling; never chain or replace the process update/shutdown.
    local previous,old_shutdown=nil,nil
    local function after(...)
        if not stopped then
            local start=os.clock()
            local was_busy=activation and activation.busy or armory_activation and armory_activation.busy
            local initializing_now=context==nil
            local ok,why=pcall(tick)
            local elapsed=os.clock()-start
            local busy=was_busy or activation and activation.busy or armory_activation and armory_activation.busy
            performance:sample(initializing_now and 'startup' or busy and 'applying' or state.armory_active and 'armory'
                or state.visible and 'deployment' or 'hidden',elapsed,tonumber(kernel.GetTickCount64()))
            if not ok then stopped=true;pcall(close_previews);pcall(function() surface:clear();if armory_ui then armory_ui:clear() end end);report('runtime.error',why) end
        end
        return ...
    end
    port_tick=function(...) return after() end
    port_shutdown=function(...)
        pcall(close_previews)
        if activation then activation:cancel('shutdown') end
        transmog:shutdown()
        stopped=true;pcall(function() surface:clear();if armory_ui then armory_ui:clear() end end)
        if not closed then performance:flush(tonumber(kernel.GetTickCount64()));report('finish_reason','shutdown');file:close();closed=true end
        if old_shutdown then return old_shutdown(...) end
    end
    state.status='scheduled';report('scheduled',true)
end
local function port_stop()
    if port_shutdown then
        local ok,why=pcall(port_shutdown)
        if not ok then return false,tostring(why) end
    end
    if port_state and rawget(_G,'CodexLoadouts')==port_state then rawset(_G,'CodexLoadouts',nil) end
    port_tick,port_shutdown,port_state=nil,nil,nil
    return true
end
return {live_lua_api=1,name='DiverKit',version=BUILD,
    on_enable=function(context)
        assert(not port_tick,'DiverKit is already active')
        if context and context.on_cleanup then context.on_cleanup(port_stop) end
        local ok,why=pcall(start_presets)
        if not ok then port_stop();error(why,0) end
        return true
    end,
    on_update=function(...) if port_tick then return port_tick(...) end end,
    on_disable=port_stop,on_cleanup_poll=port_stop}

